@js:
var s = String(result);
var host = "https://www.manhuaku.com.cn";
var hm = String(baseUrl).match(/^(https?:\/\/[^\/]+)/);
if (hm) host = hm[1];
var id = "";
var mm = String(baseUrl).match(/\/comic\/(\d+)\.html/);
if (mm) id = mm[1];
var list = [];
if (id) {
    var res = java.ajax(host + "/comic/" + id + ",{\"method\":\"POST\"}");
    if (res) {
        try {
            var d = JSON.parse(String(res)).data.chapters;
            for (var i = 0; i < d.length; i++) {
                list.push({name: d[i].chapterName, url: "/chapter/" + d[i].contentId + "-" + d[i].id + ".html"});
            }
        } catch (e) { }
    }
}
if (!list.length) {
    var re = /<a href="(\/chapter\/\d+-\d+\.html)">([^<]+)<\/a>/g, r;
    while ((r = re.exec(s)) !== null) {
        list.push({name: r[2], url: r[1]});
    }
}
list;

ruleContent.content:
@js:
var s = String(result);
var out = "";
var tm = s.match(/var totalPages\s*=\s*parseInt\('(\d+)'\)/);
var bm = s.match(/var imgBaseUrl\s*=\s*([^\n;]+);/);
// 单个拼接项求值：'a' + ('x' || 'y') 里的括号按 JS 短路语义取第一个非空字面量。
var litOf = function (t) {
    var re = /'([^']*)'|"([^"]*)"/g, m, first = null;
    while ((m = re.exec(t)) !== null) {
        var v = m[1] !== undefined ? m[1] : m[2];
        if (v.length > 0) return v;
        if (first === null) first = v;
    }
    return first === null ? "" : first;
};
// 按顶层 + 拆项（括号内的 + 不拆），逐项求值后拼接。
var evalExpr = function (e) {
    var terms = [], depth = 0, cur = "", q = "";
    for (var i = 0; i < e.length; i++) {
        var c = e.charAt(i);
        if (q) {
            cur += c;
            if (c === q && e.charAt(i - 1) !== "\\") q = "";
            continue;
        }
        if (c === "'" || c === '"') { q = c; cur += c; continue; }
        if (c === "(") { depth++; cur += c; continue; }
        if (c === ")") { depth--; cur += c; continue; }
        if (c === "+" && depth === 0) { terms.push(cur); cur = ""; continue; }
        cur += c;
    }
    terms.push(cur);
    var r = "";
    for (var j = 0; j < terms.length; j++) r += litOf(terms[j]);
    return r;
};
// 服务器对空目录（`uuid//1.webp`）直接 404，压掉拼接产生的重复斜杠，保留 `https://`。
var norm = function (u) {
    var k = u.indexOf("://");
    if (k < 0) return u.replace(/\/{2,}/g, "/");
    return u.substring(0, k + 3) + u.substring(k + 3).replace(/\/{2,}/g, "/");
};
if (tm && bm) {
    var base = norm(evalExpr(bm[1]));
    var total = parseInt(tm[1], 10);
    if (base && total > 0) {
        for (var i = 1; i <= total; i++) {
            out += '<img src="' + base + i + '.webp">';
        }
    }
}
if (!out) {
    var re2 = /data-src="([^"]+)"/g, m2;
    while ((m2 = re2.exec(s)) !== null) {
        var u = m2[1];
        if (u.indexOf("loading") > -1 || u.indexOf("/resource/") > -1) continue;
        out += '<img src="' + u + '">';
    }
}
out;
